cat > checks/authorization.cjs <<'EOF'
const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

// Exercise visibility and permissions for both fresh and already archived documents.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const owner of ['user', 'other']) {
    for (const archived of [false, true]) {
      for (const visibility of ['visible', 'missing', 'deleted', 'foreign']) {
        const document = {
          id: 'one', tenant: visibility === 'foreign' ? 'other' : 'tenant',
          owner, deleted: visibility === 'deleted', archived,
        };
        const repo = new DocumentRepository(visibility === 'missing' ? [] : [document]);
        repo.audit.push({ actor: 'previous', document: 'previous' });
        const service = new DocumentService(repo);
        const actor = { tenant: 'tenant', user: 'user', role };
        const before = JSON.parse(JSON.stringify({ documents: repo.documents, audit: repo.audit }));
        const error = visibility !== 'visible' ? 'not found'
          : role === 'admin' || (role === 'editor' && owner === 'user') ? null : 'forbidden';
        if (error) {
          assert.throws(() => service.archive(actor, 'one'), { message: error });
          assert.deepEqual({ documents: repo.documents, audit: repo.audit }, before);
        } else {
          service.archive(actor, 'one');
          assert.deepEqual(repo.documents, [{ ...document, archived: true }]);
          assert.deepEqual(repo.audit, archived ? before.audit
            : [...before.audit, { actor: 'user', document: 'one' }]);
          const audit = repo.audit.slice();
          service.archive(actor, 'one');
          assert.deepEqual(repo.audit, audit);
        }
      }
    }
  }
}
EOF
